    if (is.null(inFile))
      return(NULL)

    hr = read.csv(inFile$datapath, header = T, sep = ",")
  })
  hr2 = eventReactive(input$do2, {
    inFile2 <- input$file2

    if (is.null(inFile2))
      return(NULL)

    hr2 = read.csv(inFile2$datapath, header = T, sep = ",")
  })
  output$table <- renderDataTable({
    if(is.null(hr())){return ()}
    hr()
  })
  output$table2 <- renderDataTable({
    if(is.null(hr2())){return ()}
    hr2()
  })
  output$dt1 <- renderUI({
    dataTableOutput("table")
  })
  output$dt2 <- renderUI({
    dataTableOutput("table2")
  })
  output$contents <- renderPrint({
    return(summary(hr()))
  })
  output$contents2 <- renderPrint({
    return(summary(hr2()))
  })

  output$var1_select<-renderUI({
    selectInput("ind_var_select","Select Dataset 1 Variables", choices =as.list(names(hr())),multiple = TRUE)
  })

  output$rest_var_select<-renderUI({
    selectInput("other_var_select","Select Dataset 2 Variables",choices =as.list(names(hr2())),multiple = TRUE)
  })

  output$other_val_show<-renderPrint({
    cor.test(as.numeric(input$ind_var_select),as.numeric(input$other_var_select),method="pearson",use = "complete.obs")

  })

}
